Proceso SinValor
  Definir premio Como Entero;
  Definir puntos Como Entero <- 40;
  Si puntos > 50 Entonces
    premio <- 10;
  FinSi
  Escribir premio;
FinProceso

Proceso ConValor
  Definir premio Como Entero;
  Definir puntos Como Entero <- 40;
  Si puntos > 50 Entonces
    premio <- 10;
  Sino
    premio <- 0;
  FinSi
  Escribir premio;
FinProceso

Proceso Bucle
  Definir ultimo Como Entero;
  Definir i Como Entero <- 0;
  Mientras i < 3 Hacer
    ultimo <- i;
    i <- i + 1;
  FinMientras
  Escribir ultimo;
FinProceso
